exercise.solution:
import numpy as np
def paired_differences(a, b):
    a, b = np.asarray(a), np.asarray(b)
    if a.shape != b.shape:
        raise ValueError("Shape mismatch")
    return b - a

def effect_pp(a,b):
    if not (0 <= a <= 1 and 0 <= b <= 1): raise ValueError("invalid proportion")
    return (b-a)*100

exercise.tests:
assert abs(effect_pp(.82,.85)-3)<1e-9
assert abs(effect_pp(.9,.8)+10)<1e-9
try: effect_pp(-.1,.8)
except ValueError: pass
else: raise AssertionError("reject invalid proportions")

